"use strict";(globalThis.webpackChunkgrc||=[]).push([[42220],{31896(e){e.exports=JSON.parse('{"citeKey":"byna2009taxonomydata","slug":"byna-2009-taxonomy-data-5e3a","title":"Taxonomy of data prefetching for multicore processors","authors":["S. Byna","Y. Chen","X.-H. Sun"],"venue":"Journal of Computer Science and Technology, vol. 24, no. 3, pp. 405-417","type":"Journal","entryType":"article","date":"May, 2009","year":2009,"era":"iit","month":5,"doi":"10.1007/s11390-009-9233-4","abstract":"Data prefetching is an effective data access latency hiding technique to mask the CPU stall caused by cache misses and to bridge the performance gap between processor and memory. With hardware and/or software support, data prefetching brings data closer to a processor before it is actually needed. Many prefetching techniques have been developed for single-core processors. Recent developments in processor technology have brought multicore processors into mainstream. While some of the single-core prefetching techniques are directly applicable to multicore processors, numerous novel strategies have been proposed in the past few years to take advantage of multiple cores. This paper aims to provide a comprehensive review of the state-of-the-art prefetching techniques, and proposes a taxonomy that classifies various design concerns in developing a prefetching strategy, especially for multicore processors. We compare various existing methods through analysis as well.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2009/byna-2009-taxonomy-data-5e3a.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["multicore-scheduling"],"memberAuthors":["byna-surendra","sun-xian-he"]}')}}]);